func withTimeout<T>(_ limit: Duration, _ op: @escaping () async throws -> T) async throws -> T {
    try await withThrowingTaskGroup(of: T.self) { group in
        group.addTask { try await op() }
        group.addTask { try await Task.sleep(for: limit); throw TimeoutError() }
        defer { group.cancelAll() }    // cooperative: op must check Task.isCancelled
        return try await group.next()!
    }
}
